UPDATE cms_pages SET title='Анонимный хостинг. Инфраструктура под вашим контролем.',summary='VPS, выделенные серверы, домены и прокси от Avocado. Без KYC и проверки документов. Оплата криптовалютой. Подберём ресурсы и локацию под ваш проект.',body='Выберите конфигурацию, отправьте заявку и оплатите счёт криптовалютой. Наличие и срок выдачи подтверждаем до оплаты.',updated_at=CAST(strftime('%s','now') AS INTEGER)*1000 WHERE slug='home' AND replace(title,char(13),'')='Разрабатываем ПО. Защищаем ваши возможности.' AND replace(summary,char(13),'')='Avocado — команда разработчиков. Создаём собственные продукты Hass и Ettinger, автоматизацию и решения под вашу задачу. Домены, серверы и прокси дополняют наше ПО.' AND replace(body,char(13),'')='Собственное ПО и разработка на заказ. Обсуждаем задачи конфиденциально, запрашиваем только необходимые для работы данные. Принимаем оплату криптовалютой.';

UPDATE cms_pages SET title='Хостинг и инфраструктура',summary='VPS, выделенные серверы, домены и прокси с оплатой криптовалютой.',body='Домены, серверы и прокси Avocado для ваших проектов. В каталоге указаны ориентировочные цены для предварительного расчёта. Наличие, географию, конфигурацию и итоговую сумму подтвердим в чате перед счётом.

Стоимость регистрации и продления доменного имени согласуется до оплаты.',updated_at=CAST(strftime('%s','now') AS INTEGER)*1000 WHERE slug='catalog' AND replace(title,char(13),'')='Инфраструктура для вашего ПО' AND replace(summary,char(13),'')='Домены, серверы и прокси дополняют программные продукты Avocado.' AND replace(body,char(13),'')='Домены, серверы и прокси Avocado для ваших проектов. В каталоге указаны ориентировочные цены для предварительного расчёта. Наличие, географию, конфигурацию и итоговую сумму подтвердим в чате перед счётом.

Стоимость регистрации и продления доменного имени согласуется до оплаты.';

UPDATE cms_pages SET title='География инфраструктуры',summary='Выберите страну и посмотрите тарифы VPS, серверов и прокси в этой локации.',body='Подберём страну размещения и ресурсы под задачи вашего проекта. Наличие нужной услуги, конкретную локацию и конфигурацию подтвердим в чате.

