UPDATE cms_pages SET title='VPS-серверы',summary='Выберите страну, процессор, память и диск. Закажите VPS с оплатой криптовалютой.',body='Сравните ресурсы и выберите конфигурацию для сайта, приложения или рабочего окружения. В каждой карточке — характеристики, локация и стоимость за месяц. Наличие, итоговую сумму и срок выдачи подтвердим перед счётом.',updated_at=CAST(strftime('%s','now') AS INTEGER)*1000 WHERE slug='category-vps' AND replace(title,char(13),'')='VPS' AND replace(summary,char(13),'')='Виртуальные серверы под задачи вашего проекта.' AND replace(body,char(13),'')='Виртуальные серверы Avocado для вашего ПО. Ориентировочные цены помогут оценить бюджет. Конфигурацию, локацию, наличие и итоговую стоимость проверим перед счётом.';
